jsonTools.init:
function init(eli) {
  // ─── Settings registration ──────────────────────────────────────────
  // Three colors only for thin slice — hair STYLE, facial hair, glasses,
  // suit color, etc. wait for the next iteration.
  try {
    if (eli.settings && typeof eli.settings.register === "function") {
      eli.settings.register("mascot.skinTone", {
        default: "#ffdbb5",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotSkinTone" },
        adminPushable: true,
        describe: "ELI mascot skin tone (hex)",
      });
      eli.settings.register("mascot.hairColor", {
        // 2026-05-26: default dark brown (was black). Softer, friendlier
        // baseline that contrasts better with the navy suit + glasses.
        default: "#5c3317",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotHairColor" },
        adminPushable: true,
        describe: "ELI mascot hair color (hex)",
      });
      eli.settings.register("mascot.tieColor", {
        default: "#c62828",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotTieColor" },
        adminPushable: true,
        describe: "ELI mascot tie color (hex)",
      });
      // 2026-05-26: added 4 more dimensions — hair style, facial hair,
      // glasses style, suit color. All stay in localStorage blob alongside
      // the colors; total per-user footprint still under 200 bytes.
      eli.settings.register("mascot.hairStyle", {
        default: "professional",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotHairStyle" },
        adminPushable: true,
        describe: "ELI mascot hair style (professional|short|long|buzz|bun|bald)",
      });
      eli.settings.register("mascot.facialHair", {
        default: "none",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotFacialHair" },
        adminPushable: true,
        describe: "ELI mascot facial hair (none|mustache|goatee|beard|stubble)",
      });
      eli.settings.register("mascot.glasses", {
        default: "round",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotGlasses" },
        adminPushable: true,
        describe: "ELI mascot glasses style (round|rectangle|halfrim|none)",
      });
      eli.settings.register("mascot.suitColor", {
        default: "#1565c0",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotSuitColor" },
        adminPushable: true,
        describe: "ELI mascot suit color (hex)",
      });
    }
  } catch (_e) {}

  // ─── Color palettes ──────────────────────────────────────────────────
  // Skin tones — 8-step spectrum, named for clarity. Hex values picked
  // to read as natural human tones, not random hue jumps.
  var SKIN_TONES = [
    { hex: "#fce4d3", name: "Porcelain" },
    { hex: "#f9d4ae", name: "Fair" },
    { hex: "#ffdbb5", name: "Light" },
    { hex: "#e8b48b", name: "Medium" },
    { hex: "#c89466", name: "Tan" },
    { hex: "#a06d44", name: "Brown" },
    { hex: "#6b4226", name: "Dark Brown" },
  ];
  // 2026-05-26: Dark Brown first — matches the registered default
  // (mascot.hairColor = #5c3317) so the Reset button (which picks
  // HAIR_COLORS[0]) restores to the actual default, not Black.
  var HAIR_COLORS = [
    { hex: "#5c3317", name: "Dark Brown" },
    { hex: "#2d3748", name: "Black" },
    { hex: "#8b5a2b", name: "Brown" },
    { hex: "#c19a6b", name: "Blonde" },
    { hex: "#b85c3a", name: "Auburn" },
    { hex: "#a0a0a0", name: "Gray" },
    { hex: "#f5f5f5", name: "White" },
  ];
  var TIE_COLORS = [
    { hex: "#c62828", name: "Red" },
    { hex: "#1565c0", name: "Blue" },
    { hex: "#c9a227", name: "Gold" },
    { hex: "#0d47a1", name: "Navy" },
    { hex: "#2e7d32", name: "Green" },
    { hex: "#6a1b9a", name: "Purple" },
    { hex: "#37474f", name: "Charcoal" },
  ];
  // Suit color palette — applied to BOTH the suit body fill AND arm
  // strokes so the whole outfit recolors as one unit. Shirt + lapel
  // triangles stay white regardless.
  var SUIT_COLORS = [
    { hex: "#1565c0", name: "Navy Blue" },
    { hex: "#37474f", name: "Charcoal" },
    { hex: "#263238", name: "Black" },
    { hex: "#5d4037", name: "Brown" },
    { hex: "#1b5e20", name: "Forest" },
    { hex: "#6a1b9a", name: "Plum" },
    { hex: "#90a4ae", name: "Light Gray" },
  ];
  // Style options (non-color enums) — name+key pairs. Renderer in
  // _buildMascotSvg picks the right SVG path by key.
  var HAIR_STYLES = [
    { key: "professional", name: "Professional" },
    { key: "long",         name: "Long" },
    { key: "pigtails",     name: "Pigtails" },
    { key: "curly",        name: "Curly" },
    { key: "quiff",        name: "Quiff" },
    { key: "bun",          name: "Top Bun" },
    { key: "bald",         name: "Bald" },
  ];
  var FACIAL_HAIR_STYLES = [
    { key: "none",      name: "Clean" },
    { key: "stubble",   name: "Stubble" },
    { key: "sideburns", name: "Sideburns" },
    { key: "goatee",    name: "Full Goatee" },
    { key: "beard",     name: "Full Beard" },
  ];
  var GLASSES_STYLES = [
    { key: "round",     name: "Round" },
    { key: "rectangle", name: "Rectangle" },
    { key: "halfrim",   name: "Half-rim" },
    { key: "none",      name: "None" },
  ];

  // ─── Tiny utils ──────────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(msg, type) { if (typeof showToast === "function") showToast(msg, type || "info"); }
  function _mount() { return document.getElementById("_eli3_dashboard_root"); }

  // Trophy count cache — mirrors what trophy_gallery reads. v3 writes
  // to IDB ("stats" store, row "eli_user_stats"); v2-only installs may
  // still have it in localStorage. Read IDB first, then fall back.
  var _cachedTrophyCount = 0;
  function _refreshTrophyCount() {
    var fromLs = 0;
    try {
      var raw = eli.compat && eli.compat.lsGet ? eli.compat.lsGet("eli_user_stats") : null;
      if (raw) {
        var p = JSON.parse(raw);
        if (Array.isArray(p.unlockedTrophies)) fromLs = p.unlockedTrophies.length;
      }
    } catch (_e) {}
    if (!eli.storage || typeof eli.storage.get !== "function") {
      _cachedTrophyCount = fromLs;
      return Promise.resolve(_cachedTrophyCount);
    }
    return eli.storage.get("stats", "eli_user_stats").then(function (row) {
      if (row && Array.isArray(row.unlockedTrophies)) {
        _cachedTrophyCount = row.unlockedTrophies.length;
      } else {
        _cachedTrophyCount = fromLs;
      }
      return _cachedTrophyCount;
    }).catch(function () {
      _cachedTrophyCount = fromLs;
      return _cachedTrophyCount;
    });
  }

  // Read current value (saved pref if any, else default). The studio's
  // live-preview state mirrors this on open and tracks edits separately.
  function _getColor(key) {
    try {
      return (eli.settings && eli.settings.get) ? eli.settings.get(key) : null;
    } catch (_e) { return null; }
  }

  // ─── Mascot SVG generator ────────────────────────────────────────────
  // Takes a config object with 7 dimensions, returns SVG markup. Same
  // base geometry across all looks — only the hair, facial hair, glasses
  // SVG fragments swap by key. Suit/tie/hair/skin are color fills.
  // When eli.ui.mascot() lands in eli_kit, THIS function moves there
  // and ask_eli + eli_kit hero call it instead of their hardcoded SVGs.
  //
  // SVG layer order (back to front, so later renders on top):
  //   1. Ambient aura circle
  //   2. Suit body + lapel + tie + arms (parameterized: suitColor, tieColor)
  //   3. Head group:
  //      a. Neck + head circle (parameterized: skinTone)
  //      b. Hair (parameterized: hairStyle path + hairColor fill)
  //      c. Eyes (whites + pupils)
  //      d. Glasses (parameterized: glasses style fragment)
  //      e. Nose (uses skin-derived shadow tone)
  //      f. Mouth — smile + facial hair overlay (parameterized: facialHair fragment, hairColor fill)

  function _buildMascotSvg(opts) {
    opts = opts || {};
    var skin       = opts.skinTone   || "#ffdbb5";
    var hair       = opts.hairColor  || "#2d3748";
    var tie        = opts.tieColor   || "#c62828";
    var suit       = opts.suitColor  || "#1565c0";
    var hairStyle  = opts.hairStyle  || "professional";
    var facialHair = opts.facialHair || "none";
    var glasses    = opts.glasses    || "round";
    var noseShadow = "#ebbe9b";

    // Hair SVG fragments by style key. Bald = empty (skip the path).
    // Top bun = two layered paths (short cap on head + small knot on top).
    var hairSvg = {
      professional: '<path d="M42,69 C42,52 52,49 60,52 C68,49 78,52 78,69 C78,71 75,58 60,58 C45,58 42,71 42,69 Z" fill="' + hair + '"/>',
      // Long — extended to y=92 (was 84) and hairline raised to y=60 (was 68)
      // so forehead is fully exposed. Eyes sit at y=70 → 10px of clear
      // skin between hairline and brow.
      long:         '<path d="M42,60 C42,50 52,47 60,50 C68,47 78,50 78,60 L78,92 L74,92 C74,92 76,60 60,60 C44,60 46,92 46,92 L42,92 Z" fill="' + hair + '"/>',
      // Pigtails — base hair cap PLUS two side puffs flanking the
      // jawline. Distinct feminine silhouette (the side ellipses are
      // visible past the head circle's edges, so it doesn't look like
      // the "Short" cap from a distance).
      pigtails:     '<path d="M44,68 C44,55 53,52 60,53 C67,52 76,55 76,68 C76,70 68,60 60,60 C52,60 44,70 44,68 Z" fill="' + hair + '"/>' +
                    '<ellipse cx="40" cy="78" rx="5" ry="7.5" fill="' + hair + '"/>' +
                    '<ellipse cx="80" cy="78" rx="5" ry="7.5" fill="' + hair + '"/>',
      // Curly — scalloped/bumpy top edge that reads as texture.
      // Series of small bumps along the hairline so the silhouette
      // is clearly different from any of the smooth caps.
      curly:        '<path d="M42,68 Q43,56 47,56 Q49,52 53,53 Q55,50 60,52 Q65,50 67,53 Q71,52 73,56 Q77,56 78,68 Q76,64 73,66 Q70,68 67,65 Q64,68 60,65 Q56,68 53,65 Q50,68 47,66 Q44,64 42,68 Z" fill="' + hair + '"/>',
      // Quiff — half-height pompadour. Peak at y=46 (above the crown
      // at y=54 but only 8 units above hairline, vs Pompadour's 30).
      // Reads as "modern lifted front" — styled but not dramatic.
      quiff:        '<path d="M42,68 Q44,58 48,52 Q53,46 60,46 Q67,46 70,52 Q74,58 78,68 Z" fill="' + hair + '"/>',
      bun:          '<circle cx="60" cy="49" r="5" fill="' + hair + '"/><path d="M44,68 C44,57 53,53 60,54 C67,53 76,57 76,68 C76,70 68,60 60,60 C52,60 44,70 44,68 Z" fill="' + hair + '"/>',
      bald:         "",
    }[hairStyle] || "";

    // Facial hair colors match hair (single source of truth).
    //   Sideburns — small curved strips at the temples, no chin coverage.
    //   Stubble — wide chin area at low opacity (5-o'clock shadow).
    //   Goatee — Van Dyke style: connected mustache + chin patch (wider than the previous tiny triangle).
    //   Beard — full lower-face coverage.
    var facialSvg = {
      none:      "",
      sideburns: '<path d="M44,72 Q42,77 44,82 L46.5,82 Q47,77 46,72 Z" fill="' + hair + '"/>' +
                 '<path d="M76,72 Q78,77 76,82 L73.5,82 Q73,77 74,72 Z" fill="' + hair + '"/>',
      goatee:    // Mustache strip + chin patch + connecting strips on both sides of mouth.
                 '<path d="M54,79 Q57,77.5 60,78.5 Q63,77.5 66,79 Q63,81 60,80 Q57,81 54,79 Z" fill="' + hair + '"/>' +
                 '<path d="M53,83 Q56,84 60,83 Q64,84 67,83 Q67,90 60,91 Q53,90 53,83 Z" fill="' + hair + '"/>' +
                 '<path d="M55,80 L54,84 L55.5,84 L56,80 Z" fill="' + hair + '"/>' +
                 '<path d="M65,80 L66,84 L64.5,84 L64,80 Z" fill="' + hair + '"/>',
      beard:     '<path d="M46,80 Q48,90 60,91 Q72,90 74,80 Q68,86 60,86 Q52,86 46,80 Z" fill="' + hair + '"/>',
      stubble:   '<path d="M46,80 Q48,90 60,91 Q72,90 74,80 Q68,86 60,86 Q52,86 46,80 Z" fill="' + hair + '" opacity="0.32"/>',
    }[facialHair] || "";

    // Glasses fragments. "none" suppresses everything. Round = current
    // default. Rectangle = trade circles for rounded rects.
    var glassesSvg = {
      round:
        '<circle cx="52" cy="70" r="5.5" fill="rgba(144,202,249,0.15)" stroke="#0d47a1" stroke-width="1.2"/>' +
        '<circle cx="68" cy="70" r="5.5" fill="rgba(144,202,249,0.15)" stroke="#0d47a1" stroke-width="1.2"/>' +
        '<line x1="57" y1="70" x2="63" y2="70" stroke="#0d47a1" stroke-width="1.2"/>' +
        '<line x1="46.5" y1="70" x2="42.5" y2="68" stroke="#0d47a1" stroke-width="1"/>' +
        '<line x1="73.5" y1="70" x2="77.5" y2="68" stroke="#0d47a1" stroke-width="1"/>',
      rectangle:
        '<rect x="46" y="66" width="12" height="8" rx="1.2" fill="rgba(144,202,249,0.15)" stroke="#0d47a1" stroke-width="1.2"/>' +
        '<rect x="62" y="66" width="12" height="8" rx="1.2" fill="rgba(144,202,249,0.15)" stroke="#0d47a1" stroke-width="1.2"/>' +
        '<line x1="58" y1="70" x2="62" y2="70" stroke="#0d47a1" stroke-width="1.2"/>' +
        '<line x1="46" y1="70" x2="42.5" y2="68" stroke="#0d47a1" stroke-width="1"/>' +
        '<line x1="74" y1="70" x2="77.5" y2="68" stroke="#0d47a1" stroke-width="1"/>',
      halfrim:
        '<path d="M46.5,70 Q52,75 57.5,70" stroke="#0d47a1" stroke-width="1.4" fill="none" stroke-linecap="round"/>' +
        '<path d="M62.5,70 Q68,75 73.5,70" stroke="#0d47a1" stroke-width="1.4" fill="none" stroke-linecap="round"/>' +
        '<line x1="57.5" y1="70" x2="62.5" y2="70" stroke="#0d47a1" stroke-width="1.2"/>',
      none: "",
    }[glasses] || "";

    return '' +
      '<svg viewBox="0 0 120 120" width="100%" height="100%" class="_eli3_ems_svg">' +
        '<circle cx="60" cy="65" r="45" fill="rgba(147,197,253,0.18)"/>' +
        // Suit body (parameterized — suitColor)
        '<path d="M38,100 C34,110 34,120 34,120 L86,120 C86,120 86,110 82,100 Z" fill="' + suit + '"/>' +
        '<path d="M53,100 L67,100 L60,112 Z" fill="#ffffff"/>' +
        // Tie
        '<path d="M58,105 L62,102 L63,120 L57,120 Z" fill="' + tie + '"/>' +
        // Arms (parameterized — suitColor)
        '<path d="M38,102 Q34,112 34,120" stroke="' + suit + '" stroke-width="4.5" fill="none" stroke-linecap="round"/>' +
        '<path d="M82,102 Q86,112 86,120" stroke="' + suit + '" stroke-width="4.5" fill="none" stroke-linecap="round"/>' +
        // Head group
        '<g class="_eli3_ems_head">' +
          '<rect x="55" y="85" width="10" height="15" rx="2" fill="' + skin + '"/>' +
          '<circle cx="60" cy="72" r="18" fill="' + skin + '"/>' +
          hairSvg +
          // Eyes — _eli3_ems_eyes group toggles opacity (blink); inner
          // _eli3_ems_eyeball circles translate (pupil tracking).
          '<g class="_eli3_ems_eyes">' +
            '<ellipse cx="52" cy="70" rx="3.5" ry="3.5" fill="#ffffff"/>' +
            '<circle cx="52" cy="70" r="1.8" fill="#1a202c" class="_eli3_ems_eyeball"/>' +
            '<ellipse cx="68" cy="70" rx="3.5" ry="3.5" fill="#ffffff"/>' +
            '<circle cx="68" cy="70" r="1.8" fill="#1a202c" class="_eli3_ems_eyeball"/>' +
          '</g>' +
          // Eyelids — opacity-flipped against eyes group so the lid lines
          // appear ONLY during the blink frames.
          '<g class="_eli3_ems_eyelids" style="opacity:0;">' +
            '<line x1="48" y1="70" x2="56" y2="70" stroke="#4a5568" stroke-width="1.2" stroke-linecap="round"/>' +
            '<line x1="64" y1="70" x2="72" y2="70" stroke="#4a5568" stroke-width="1.2" stroke-linecap="round"/>' +
          '</g>' +
          glassesSvg +
          // Nose
          '<path d="M60,70 L58.5,75 L61.5,75 Z" fill="' + noseShadow + '"/>' +
          // Smile (rendered before facial hair so beard sits in front)
          '<path d="M55,81 Q60,85 65,81" stroke="#a04040" stroke-width="1.5" fill="none" stroke-linecap="round"/>' +
          facialSvg +
        '</g>' +
      '</svg>';
  }

  // ─── Customizer UI ───────────────────────────────────────────────────
  // Refreshes the trophy count async before rendering so the lock
  // overlay shows the right "X / 40 trophies" number. The IDB read
  // is fast (typically <20ms) — no spinner needed.
  function _showCustomizer() {
    _refreshTrophyCount().then(_renderCustomizer);
  }
  function _renderCustomizer() {
    var m = _mount();
    if (!m) { _toast("Dashboard root missing — reload", "err"); return; }
    if (window.eli && window.eli.ui && window.eli.ui.claimOutput) window.eli.ui.claimOutput();
    m.style.display = "";
    m.innerHTML = "";

    // Live-edit state — initialized from current saved/default values.
    var state = {
      skinTone:   _getColor("mascot.skinTone")   || SKIN_TONES[2].hex,
      hairColor:  _getColor("mascot.hairColor")  || HAIR_COLORS[0].hex,
      tieColor:   _getColor("mascot.tieColor")   || TIE_COLORS[0].hex,
      suitColor:  _getColor("mascot.suitColor")  || SUIT_COLORS[0].hex,
      hairStyle:  _getColor("mascot.hairStyle")  || "professional",
      facialHair: _getColor("mascot.facialHair") || "none",
      glasses:    _getColor("mascot.glasses")    || "round",
    };
    // Trophy gate — facial hair + the entire Style & Accessories card
    // (suit, tie, glasses) unlock at 40 trophies (rank: Strategist).
    // Below that threshold the controls render but are disabled and
    // overlaid with a clear "earn N more trophies" call to action.
    var _trophyCount = (window.eli && window.eli.ui && window.eli.ui.mascotTrophyCount)
      ? window.eli.ui.mascotTrophyCount() : 0;
    var _unlocked = _trophyCount >= 40;

    // Shell — full-area takeover like Settings.
    var root = document.createElement("div");
    root.className = "_eli3_ems_root";
    root.innerHTML =
      '<div class="_eli3_ems_header">' +
        '<button data-act="back" class="_eli3_ems_back" title="Back to dashboard">←</button>' +
        '<div class="_eli3_ems_title">Personalize ELI</div>' +
      '</div>' +
      '<div class="_eli3_ems_body">' +
        // Live preview — compact, sits up top so users see ELI without
        // scrolling. Smaller mascot (110×138 vs the previous 160×200)
        // and tighter padding to leave room for the 2-column control grid.
        '<div class="_eli3_ems_preview">' +
          '<div class="_eli3_ems_glow" aria-hidden="true"></div>' +
          '<div class="_eli3_ems_mascot_wrap" data-slot="mascot"></div>' +
        '</div>' +
        // Controls — 2-column grid.
        //   LEFT  (Face): skin, hair color, hair style, facial hair*
        //   RIGHT (Style & Accessories): suit, tie, glasses — LOCKED until 40 trophies
        // *facial hair is also gated at 40 trophies (it's a "premium" customization).
        // On narrow viewports auto-fit collapses to one column.
        '<div class="_eli3_ems_columns">' +
          '<div class="_eli3_ems_controls">' +
            '<div class="_eli3_ems_section_title">Face</div>' +
            _renderSwatchRow("Skin tone", "skinTone", SKIN_TONES, state.skinTone) +
            _renderSwatchRow("Hair color", "hairColor", HAIR_COLORS, state.hairColor) +
            _renderOptionRow("Hair style", "hairStyle", HAIR_STYLES, state.hairStyle) +
            _renderLockableRow(_unlocked,
              _renderOptionRow("Facial hair", "facialHair", FACIAL_HAIR_STYLES, state.facialHair)) +
          '</div>' +
          _renderLockableSection(_unlocked, _trophyCount,
            '<div class="_eli3_ems_section_title">Style &amp; Accessories</div>' +
            _renderSwatchRow("Suit color", "suitColor", SUIT_COLORS, state.suitColor) +
            _renderSwatchRow("Tie color", "tieColor", TIE_COLORS, state.tieColor) +
            _renderOptionRow("Glasses", "glasses", GLASSES_STYLES, state.glasses)
          ) +
        '</div>' +
        // Footer actions
        '<div class="_eli3_ems_footer">' +
          '<button data-act="reset" class="_eli3_ems_btn _eli3_ems_btn_secondary" title="Restore default appearance">↺ Reset to default</button>' +
          '<div style="flex:1"></div>' +
          '<button data-act="cancel" class="_eli3_ems_btn _eli3_ems_btn_secondary">Cancel</button>' +
          '<button data-act="save" class="_eli3_ems_btn _eli3_ems_btn_primary">💾 Save</button>' +
        '</div>' +
      '</div>';
    m.appendChild(root);

    var mascotSlot = root.querySelector("[data-slot='mascot']");
    function _repaintMascot() {
      mascotSlot.innerHTML = _buildMascotSvg(state);
    }
    _repaintMascot();

    // Common click handler — swatches (data-swatch) and option pills
    // (data-option) both write to state[key], toggle the selected class
    // among siblings sharing the same data-key, and repaint.
    function _wirePicker(el) {
      el.onclick = function () {
        var key = el.getAttribute("data-key");
        var val = el.getAttribute("data-swatch") || el.getAttribute("data-option");
        var selectedClass = el.classList.contains("_eli3_ems_option")
          ? "_eli3_ems_option_selected" : "_eli3_ems_swatch_selected";
        state[key] = val;
        root.querySelectorAll('[data-key="' + key + '"]').forEach(function (sib) {
          var sibVal = sib.getAttribute("data-swatch") || sib.getAttribute("data-option");
          sib.classList.toggle(selectedClass, sibVal === val);
        });
        _repaintMascot();
      };
    }
    root.querySelectorAll("[data-swatch],[data-option]").forEach(_wirePicker);

    root.querySelector("[data-act='back']").onclick = _goHome;
    root.querySelector("[data-act='cancel']").onclick = _goHome;
    root.querySelector("[data-act='reset']").onclick = function () {
      state.skinTone   = SKIN_TONES[2].hex;
      state.hairColor  = HAIR_COLORS[0].hex;
      state.tieColor   = TIE_COLORS[0].hex;
      state.suitColor  = SUIT_COLORS[0].hex;
      state.hairStyle  = "professional";
      state.facialHair = "none";
      state.glasses    = "round";
      // Refresh "selected" indicators across both swatches and option pills.
      [
        ["skinTone",   state.skinTone,   "swatch"],
        ["hairColor",  state.hairColor,  "swatch"],
        ["tieColor",   state.tieColor,   "swatch"],
        ["suitColor",  state.suitColor,  "swatch"],
        ["hairStyle",  state.hairStyle,  "option"],
        ["facialHair", state.facialHair, "option"],
        ["glasses",    state.glasses,    "option"],
      ].forEach(function (tup) {
        var key = tup[0], val = tup[1], kind = tup[2];
        var selectedClass = kind === "option" ? "_eli3_ems_option_selected" : "_eli3_ems_swatch_selected";
        root.querySelectorAll('[data-key="' + key + '"]').forEach(function (sib) {
          var sibVal = sib.getAttribute("data-swatch") || sib.getAttribute("data-option");
          sib.classList.toggle(selectedClass, sibVal === val);
        });
      });
      _repaintMascot();
      _toast("Preview reset to default — click Save to apply.", "info");
    };
    root.querySelector("[data-act='save']").onclick = function () {
      try {
        var layer = (eli.settings && eli.settings.LAYER_USER) || "user";
        eli.settings.set("mascot.skinTone",   state.skinTone,   { layer: layer });
        eli.settings.set("mascot.hairColor",  state.hairColor,  { layer: layer });
        eli.settings.set("mascot.tieColor",   state.tieColor,   { layer: layer });
        eli.settings.set("mascot.suitColor",  state.suitColor,  { layer: layer });
        eli.settings.set("mascot.hairStyle",  state.hairStyle,  { layer: layer });
        eli.settings.set("mascot.facialHair", state.facialHair, { layer: layer });
        eli.settings.set("mascot.glasses",    state.glasses,    { layer: layer });
        // Bus event so future ask_eli / eli_kit listeners can repaint.
        try { eli.bus.emit("mascot:customized", { state: state }); } catch (_e) {}
        _toast("✅ ELI updated.", "ok");
        try { eli.stats.record("appOpenedMascotStudio"); } catch (_) {}
      } catch (err) {
        _toast("Save failed: " + (err && err.message), "err");
      }
    };
  }

  function _renderSwatchRow(label, key, palette, currentHex) {
    return '<div class="_eli3_ems_row">' +
      '<div class="_eli3_ems_row_label">' + _esc(label) + '</div>' +
      '<div class="_eli3_ems_swatches">' +
        palette.map(function (sw) {
          var selected = sw.hex.toLowerCase() === String(currentHex || "").toLowerCase();
          return '<button class="_eli3_ems_swatch' + (selected ? ' _eli3_ems_swatch_selected' : '') + '"' +
            ' data-key="' + _esc(key) + '" data-swatch="' + _esc(sw.hex) + '"' +
            ' style="background:' + _esc(sw.hex) + ';"' +
            ' title="' + _esc(sw.name) + '">' +
            '</button>';
        }).join("") +
      '</div>' +
    '</div>';
  }

  // Option pills — same row structure as swatches but renders text labels
  // for enums (hair style, facial hair, glasses style). data-option holds
  // the key value; selected pill gets _eli3_ems_option_selected class.
  function _renderOptionRow(label, key, options, currentKey) {
    return '<div class="_eli3_ems_row">' +
      '<div class="_eli3_ems_row_label">' + _esc(label) + '</div>' +
      '<div class="_eli3_ems_options">' +
        options.map(function (opt) {
          var selected = opt.key === currentKey;
          return '<button class="_eli3_ems_option' + (selected ? ' _eli3_ems_option_selected' : '') + '"' +
            ' data-key="' + _esc(key) + '" data-option="' + _esc(opt.key) + '">' +
            _esc(opt.name) +
            '</button>';
        }).join("") +
      '</div>' +
    '</div>';
  }

  // Lock wrappers — render the inner HTML normally and overlay a "locked"
  // tint + small lock chip if !unlocked. The CSS class disables pointer
  // events on the children so clicks fall through to do nothing (Save
  // still won't write changed values because state can't be edited from
  // a locked control).
  //
  // _renderLockableRow: small inline lock indicator inside the row label
  //                     (used for the Facial Hair row inside the Face card).
  // _renderLockableSection: whole-card overlay with prominent banner
  //                     (used for the Style & Accessories card).
  function _renderLockableRow(unlocked, innerHtml) {
    if (unlocked) return innerHtml;
    return '<div class="_eli3_ems_locked_row">' +
      innerHtml +
      '<div class="_eli3_ems_lock_chip">🔒 Unlocks at 40 trophies</div>' +
    '</div>';
  }
  function _renderLockableSection(unlocked, trophyCount, innerHtml) {
    if (unlocked) return '<div class="_eli3_ems_controls">' + innerHtml + '</div>';
    var need = 40 - trophyCount;
    return '<div class="_eli3_ems_controls _eli3_ems_locked_section">' +
      innerHtml +
      '<div class="_eli3_ems_lock_overlay">' +
        '<div class="_eli3_ems_lock_card">' +
          '<div class="_eli3_ems_lock_icon">🔒</div>' +
          '<div class="_eli3_ems_lock_title">Style &amp; Accessories</div>' +
          '<div class="_eli3_ems_lock_msg">' +
            'Unlock suit colors, tie colors, glasses, and facial hair styles ' +
            'when you reach <b>40 trophies</b> (Strategist rank).' +
          '</div>' +
          '<div class="_eli3_ems_lock_progress">' +
            '<b>' + trophyCount + '</b> / 40 trophies — ' +
            '<b>' + Math.max(0, need) + '</b> to go' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  }

