      '._eli3_ems_glow{position:absolute;top:0;left:50%;transform:translateX(-50%);width:150px;height:150px;border-radius:50%;background:radial-gradient(circle at 50% 45%,rgba(253,224,71,0.20) 0%,rgba(147,197,253,0.16) 35%,transparent 70%);animation:_eli3_ems_glow_pulse 3.2s ease-in-out infinite;pointer-events:none;z-index:0;}' +
