      '._eli3_ems_swatches{display:flex;flex-wrap:wrap;gap:8px;}' +
      '._eli3_ems_swatch{width:34px;height:34px;border-radius:50%;border:2px solid transparent;cursor:pointer;padding:0;box-shadow:0 1px 2px rgba(0,0,0,0.12),inset 0 1px 2px rgba(255,255,255,0.25);transition:transform 0.15s ease,border-color 0.15s ease;}' +
