  // ─── Expose eli.ui.mascot() — the shared SVG builder ─────────────────
  // Public API. ask_eli + eli_kit + any future tool call this to render
  // the user's customized mascot. With no opts, reads all 7 settings.
  // opts can override individual fields (e.g., for hover state previews).
  //   eli.ui.mascot()                     → user's saved look
  //   eli.ui.mascot({ hairStyle: "bun" }) → user's saved look with bun
  // Returns SVG markup string — caller injects via innerHTML.
  if (window.eli && window.eli.ui) {
    window.eli.ui.mascot = function (opts) {
      opts = opts || {};
      // Fill in any unspecified fields from settings (with hardcoded
      // safety defaults if settings registry isn't up yet).
      var merged = {
        skinTone:   opts.skinTone   || _getColor("mascot.skinTone")   || "#ffdbb5",
        hairColor:  opts.hairColor  || _getColor("mascot.hairColor")  || "#2d3748",
        tieColor:   opts.tieColor   || _getColor("mascot.tieColor")   || "#c62828",
        suitColor:  opts.suitColor  || _getColor("mascot.suitColor")  || "#1565c0",
        hairStyle:  opts.hairStyle  || _getColor("mascot.hairStyle")  || "professional",
        facialHair: opts.facialHair || _getColor("mascot.facialHair") || "none",
        glasses:    opts.glasses    || _getColor("mascot.glasses")    || "round",
      };
      return _buildMascotSvg(merged);
    };
    // Trophy gate helper — single source of truth for the 40-trophy
    // unlock. v3 stores stats in IDB (store="stats", row="eli_user_stats")
    // with a localStorage fallback for legacy v2-only installs. The
    // getter is sync (returns a cached count); _refreshTrophyCount kicks
    // off an async read that updates the cache. Callers that need a
    // fresh number should await _refreshTrophyCount() first.
    window.eli.ui.mascotUnlockedAt = 40;
    window.eli.ui.mascotTrophyCount = function () { return _cachedTrophyCount; };
    window.eli.ui.mascotPremiumUnlocked = function () {
      return _cachedTrophyCount >= window.eli.ui.mascotUnlockedAt;
    };
    window.eli.ui.mascotRefreshTrophyCount = _refreshTrophyCount;
    // Warm the cache at preload so the customizer's first read has
    // accurate data even if the user opens it immediately.
    _refreshTrophyCount();
  }

  // Legacy alias retained for any debug console snippets that used it.
  if (window.eli) window.eli._mascotPreview = _buildMascotSvg;

  eli.log.event("tool", "eli_mascot_studio_initialized", {});
